UPDATE products SET blurb = 'The Covington Super Diamond Lapidary Maxi Lap is a compact, portable flat lap with a cast aluminum body and a 1/3 hp motor with a carrying handle.

Quick-change aluminum heads without a center hole make it fast to switch stages, and a water manifold, pump and tubing are set up for you. The package includes a perforated diamond disc system (coarse, medium and fine), a 1200 grit diamond disc and a leather polishing disc.', features = '["Cast aluminum body", "1/3 hp motor with carrying handle", "Quick-change aluminum heads (no hole)", "Water manifold assembly, pump, tubing", "Compact and portable"]', included = '["Perforated diamond disc system (coarse, medium, fine)", "1200 grit diamond disc", "Leather polishing disc", "Drain kit", "Book about using diamond abrasives", "Instructions"]', specs = '{}', warranty = NULL WHERE id = 'covington-super-diamond-lapidary-maxi-lap-flat-lap-machine';
UPDATE products SET blurb = 'The Covington 8 Inch Perfect Diamond Lapidary Maxi Lap is a quiet, portable flat lap running at 1410 rpm on a 1/3 hp motor with a carrying handle.

The body is heavy-duty cast aluminum with quick-change aluminum heads (no center hole), and a water manifold and pump are included. It comes with an aluminum head with steel disc plus nickel-bond discs starting at 100 and 260 grit. Manufacturer\'s warranty applies.', features = '["Heavy duty cast aluminum body", "Quick-change aluminum heads (no hole)", "Water manifold and pump", "1/3 hp motor with carrying handle", "Runs quietly at 1410 rpm", "Compact and portable"]', included = '["One aluminum head with steel disc", "100 grit nickel bond disc", "260 grit nickel bond disc", "325 grit resin bond disc", "600 grit resin bond disc", "1200 grit resin bond disc", "Synthetic felt disc"]', specs = '{"Motor": "1/3 hp", "Speed": "1410 rpm"}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-8-inch-perfect-diamond-lapidary-maxi-lap';
UPDATE products SET blurb = 'The Covington Perfect Diamond Glass Maxi Lap is a portable flat lap for glass, available in 8 in and 10 in sizes.

