UPDATE products SET blurb = 'The Covington Variable Speed Grinder Polisher has a 1/2 hp high-torque motor with speed control from 800 to 1725 rpm.

The arbor is powder-coated cast aluminum on a 1 x 18 in shaft with neoprene-sealed ball bearings greased for life, and it stands on an aluminum-topped Lam-I-Cushion base. Flanges, nuts, drive pulley, belt guard, water valves and drains are included. Manufacturer\'s warranty applies.', features = '["1\\" x 18\\" shaft", "1/2 hp high torque motor", "Neoprene sealed ball bearings, greased for life", "Speed control 800-1725 rpm", "Powder coated cast aluminum arbor", "Aluminum-topped Lam-I-Cushion base"]', included = '["Flanges", "Nuts", "Drive pulley", "Belt guard", "Water valves and drains"]', specs = '{"Speed range": "800-1725 rpm"}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-variable-speed-grinder-polisher';
UPDATE products SET blurb = 'The Covington Two Station Open Arbor is a build-your-own grinder/polisher with a heavy-duty cast aluminum arbor and a V-belt drive.

